import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int f = 0;
        String str = scanner.nextLine();
        String str2 = "";
        List<String> ret = new ArrayList<>();

        str2 += str.charAt(0);
        ret.add(str2);

        int i = 1;
        while (i < str.length() - 1) {
            String x = "";
            String y = "";

            if (i + 2 < str.length() - 1) {
                x += str.charAt(i);
                x += str.charAt(i + 1);
                x += str.charAt(i + 2);
            }
            if (i + 1 < str.length() - 1) {
                y += str.charAt(i);
                y += str.charAt(i + 1);
            }

            if (x.equals("dot")) {
                str2 += '.';
                for (int j = 0; j < ret.size(); j++) {
                    ret.set(j, ret.get(j) + ".");
                }
                i += 3; // skip over 'dot'
            } else if (y.equals("at")) {
                f++;
                for (int j = 0; j < f - 1; j++) {
                    ret.set(j, ret.get(j) + "at");
                }
                for (int j = f - 1; j < ret.size(); j++) {
                    ret.set(j, ret.get(j) + "@");
                }
                str2 += str.charAt(i);
                str2 += str.charAt(i + 1);
                ret.add(str2);
                i += 2; // skip over 'at'
            } else {
                str2 += str.charAt(i);
                for (int j = 0; j < ret.size(); j++) {
                    ret.set(j, ret.get(j) + str.charAt(i));
                }
                i++;
            }
        }
        // Append last character
        for (int j = 0; j < ret.size(); j++) {
            ret.set(j, ret.get(j) + str.charAt(str.length() - 1));
        }

        Collections.sort(ret);
        System.out.println(ret.get(0));
    }
}
